void plotPie(GalleryCtx& ctx) {
    Figure fig(1, 1);
    auto* ax = fig.addAxes();
    ax->setStyle(galleryStyle());
    ax->setTitle("Pie");
    // Pie charts don't show axes/spines/ticks/grid.
    ax->style().xAxis.visible = false;
    ax->style().yAxis.visible = false;
    ax->style().xAxis.grid = false;
    ax->style().yAxis.grid = false;
    PieData pd;
    pd.values = {30, 20, 25, 15, 10};
    pd.labels = {"A", "B", "C", "D", "E"};
    // matplotlib default color cycle: tab10
    pd.colors = {
        Color::fromRgba8(31, 119, 180),   // blue
        Color::fromRgba8(255, 127, 14),   // orange
        Color::fromRgba8(44, 160, 44),    // green
        Color::fromRgba8(214, 39, 40),    // red
        Color::fromRgba8(148, 103, 189),  // purple
    };
    ax->addPlot(std::make_unique<PiePlot>(std::move(pd)));
    ctx.render(fig, "pie");
}

void plotBox(GalleryCtx& ctx) {
    Figure fig(1, 1);
    auto* ax = setupAxes(fig, "Box Plot");
    ax->style().xAxis.label = "Group";
    ax->style().yAxis.label = "Value";
    std::normal_distribution<float> d(0, 1);
    std::vector<std::vector<float>> groups;
    for (int g = 0; g < 4; ++g) {
        std::vector<float> group;
        std::normal_distribution<float> gd(g, 1.0f + g * 0.2f);
        for (int i = 0; i < 100; ++i)
            group.push_back(gd(rng()));
        groups.push_back(std::move(group));
    }
    BoxPlotConfig cfg;
    cfg.labels = {"G1", "G2", "G3", "G4"};
    ax->addPlot(std::make_unique<BoxPlot>(std::move(groups), cfg));
    ctx.render(fig, "box");
}

void plotViolin(GalleryCtx& ctx) {
    Figure fig(1, 1);
    auto* ax = setupAxes(fig, "Violin Plot");
    ax->style().xAxis.label = "Group";
    ax->style().yAxis.label = "Value";
    std::vector<std::vector<float>> groups;
    for (int g = 0; g < 4; ++g) {
        std::vector<float> group;
        std::normal_distribution<float> gd(g * 0.5f, 1.0f);
        for (int i = 0; i < 150; ++i)
            group.push_back(gd(rng()));
        groups.push_back(std::move(group));
    }
    ViolinConfig cfg;
    cfg.labels = {"G1", "G2", "G3", "G4"};
    // Set categorical X-axis tick labels at violin centers (x=1,2,3,4).
    ax->style().xAxis.ticks.positions = {1.0f, 2.0f, 3.0f, 4.0f};
    ax->style().xAxis.ticks.labels = {"G1", "G2", "G3", "G4"};
    ax->addPlot(std::make_unique<ViolinPlot>(std::move(groups), cfg));
    ctx.render(fig, "violin");
}

void plotStack(GalleryCtx& ctx) {
    Figure fig(1, 1);
    auto* ax = setupAxes(fig, "Stack Plot");
    ax->style().xAxis.label = "X";
    ax->style().yAxis.label = "Y";
    auto x = linspace(0, 10, 50);
    std::vector<std::vector<float>> ys;
    for (int s = 0; s < 3; ++s) {
        std::vector<float> y;
        for (float xi : x)
            y.push_back(std::sin(xi + s) * 2 + 3);
        ys.push_back(std::move(y));
    }
    std::vector<Color> colors = {
        Color::fromRgba8(31, 119, 180),
        Color::fromRgba8(255, 127, 14),
        Color::fromRgba8(44, 160, 44),
    };
    std::vector<std::string> labels = {"A", "B", "C"};
    ax->addPlot(std::make_unique<StackPlot>(x, std::move(ys), colors, labels));
    ax->style().legend.visible = true;
    ctx.render(fig, "stack");
}

