void plotHeatmap(GalleryCtx& ctx) {
    Figure fig(1, 1);
    auto* ax = setupAxes(fig, "Heatmap");
    Grid2D grid;
    grid.width = 30;
    grid.height = 20;
    grid.xRange = {0, 10};
    grid.yRange = {0, 10};
    grid.values.resize(30 * 20);
    for (uint32_t j = 0; j < 20; ++j)
        for (uint32_t i = 0; i < 30; ++i) {
            float x = float(i) / 29 * 10;
            float y = float(j) / 19 * 10;
            grid.values[j * 30 + i] = std::sin(x * 0.5f) * std::cos(y * 0.5f);
        }
    ax->addPlot(std::make_unique<HeatmapPlot>(std::move(grid)));
    ax->style().colorbar.visible = true;
    ax->style().colorbar.colormap = "viridis";
    ctx.render(fig, "heatmap");
}

