void plotContour(GalleryCtx& ctx) {
    Figure fig(1, 1);
    auto* ax = setupAxes(fig, "Contour");
    Grid2D grid;
    grid.width = 50;
    grid.height = 50;
    grid.xRange = {-3, 3};
    grid.yRange = {-3, 3};
    grid.values.resize(50 * 50);
    for (uint32_t j = 0; j < 50; ++j)
        for (uint32_t i = 0; i < 50; ++i) {
            float x = -3 + float(i) / 49 * 6;
            float y = -3 + float(j) / 49 * 6;
            grid.values[j * 50 + i] = std::sin(x) * std::cos(y);
        }
    ContourConfig cfg;
    ax->addPlot(std::make_unique<ContourPlot>(std::move(grid), cfg));
    ctx.render(fig, "contour");
}

